window.__finlexDocLoaded(10132,{"id":10132,"articles":[{"id":1000574,"no":"Overview","heading":"Official Overview & Scope (IFRS Foundation)","text":"IFRIC 22 is effective 1 January 2018.\n\nIFRIC 22 clarifies which exchange rate to use in transactions that involve advance consideration paid or received in a foreign currency.","seq":0},{"id":1000575,"no":"IFRIC 22.8–9","heading":"Foreign Currency Advance Consideration","text":"For determining the spot exchange rate on initial recognition of the related asset, expense, or income, the date of the transaction is the date on which the entity initially recognises the non-monetary prepayment asset or deferred income liability (no retranslation later).","seq":1},{"id":1000576,"no":"History","heading":"Standard History & Amendments","text":"In December 2016 the International Accounting Standards Board issued IFRIC 22 Foreign Currency Transactions and Advance Consideration. It was developed by the Interpretations Committee.\n\nOther Standards have made minor consequential amendments to IFRIC 22, including IFRS 17 Insurance Contracts (issued May 2017) and Amendments to References to the Conceptual Framework in IFRS Standards (issued March 2018).","seq":2},{"id":1000577,"no":"Support","heading":"Related Projects & Implementation Support","text":"[Related completed projects]\n• Foreign Currency Transactions and Advance Consideration (Amendments to IAS 21)\n\n[Related IFRS Standards]\n• IAS 21 The Effects of Changes in Foreign Exchange Rates","seq":3},{"id":1000578,"no":"References","heading":"Official Text Link & Public Practical Guidance","text":"Official IFRS Foundation Page (English): https://www.ifrs.org/issued-standards/list-of-standards/ifric-22-foreign-currency-transactions-and-advance-consideration/\nAccess Note: Free access to the unaccompanied text of IFRS Accounting Standards on ifrs.org requires a free registered IFRS.org account; Basis for Conclusions and Illustrative Examples require an IFRS Digital Subscription.\nPublic Companion Overview: KPMG Insights into IFRS — An Overview (Sept 2026): https://assets.kpmg.com/content/dam/kpmgsites/xx/pdf/ifrg/2026/isg-2026-insights-an-overview.pdf","seq":4}]});
